    "route": "component",
    "label": "설명과 추가 정보",
    "source": "<script setup lang=\"ts\">\nimport { ref, nextTick, onMounted, onBeforeUnmount } from 'vue';\nimport { SCard, SBtn } from '@solyi/vue-ui';\nconst tooltip = ref(false),\n  open = ref(false),\n  root = ref<HTMLElement | null>(null);\nfunction close(restore = true) {\n  open.value = false;\n  if (restore)\n    nextTick(() => document.getElementById('recipe-popover-open')?.focus());\n}\nfunction toggle() {\n  if (open.value) close();\n  else {\n    open.value = true;\n    nextTick(() => document.getElementById('recipe-popover-close')?.focus());\n  }\n}\nfunction escape() {\n  tooltip.value = false;\n  if (open.value) close();\n}\nfunction focusout() {\n  nextTick(() => {\n    if (root.value && !root.value.contains(document.activeElement)) {\n      tooltip.value = false;\n      close(false);\n    }\n  });\n}\nfunction outside(e: Event) {\n  if (root.value && !root.value.contains(e.target as Node)) {\n    tooltip.value = false;\n    close(false);\n  }\n}\nonMounted(() => document.addEventListener('pointerdown', outside));\nonBeforeUnmount(() => document.removeEventListener('pointerdown', outside));\n</script>\n<template>\n  <SCard\n    :heading-level=\"2\"\n    title=\"짧은 설명과 추가 정보\"\n  >\n    <p>\n      전용 Tooltip/Popover export 대신 SBtn과 SCard를 연결한 Vue 조합입니다.\n    </p>\n    <div\n      ref=\"root\"\n      style=\"position: relative\"\n      @focusout=\"focusout\"\n      @keydown.esc.stop.prevent=\"escape\"\n    >\n      <SBtn\n        aria-describedby=\"recipe-tooltip\"\n        @mouseenter=\"tooltip = true\"\n        @mouseleave=\"tooltip = false\"\n        @focus=\"tooltip = true\"\n        @blur=\"tooltip = false\"\n        @click=\"tooltip = !tooltip\"\n      >\n        짧은 설명\n      </SBtn>\n      <span\n        id=\"recipe-tooltip\"\n        v-show=\"tooltip\"\n        role=\"tooltip\"\n        class=\"sol-tooltip\"\n        @mouseenter=\"tooltip = true\"\n        @mouseleave=\"tooltip = false\"\n        style=\"position: absolute; top: calc(100% + 8px); left: 0\"\n      >\n        가상 기록을 찾는 도구예요.\n      </span>\n      <SBtn\n        id=\"recipe-popover-open\"\n        :aria-expanded=\"open\"\n        aria-controls=\"recipe-popover\"\n        @click=\"toggle\"\n      >\n        추가 정보\n      </SBtn>\n      <SCard\n        id=\"recipe-popover\"\n        v-show=\"open\"\n        title=\"추가 정보\"\n        style=\"margin-top: 16px\"\n      >\n        <p>읽을 내용과 닫기 행동이 있는 가상 정보입니다.</p>\n        <SBtn\n          id=\"recipe-popover-close\"\n          variant=\"inline\"\n          @click=\"close()\"\n        >\n          정보 닫기\n        </SBtn>\n      </SCard>\n    </div>\n  </SCard>\n</template>\n"
